'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

const err = (fn, type, re) => assert.throws(fn, e => e instanceof type && (!re || re.test(e.message)));

assert.deepEqual(parse(''), []);
assert.deepEqual(parse('\uFEFF'), []);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\r\nb\rc\n'), [['a'], ['b'], ['c']]);
assert.deepEqual(parse('a"b",c'), [['a"b"', 'c']]);
assert.deepEqual(parse('"x\r\ny\rz"'), [['x\r\ny\rz']]);
assert.deepEqual(parse('\uFEFFa,\uFEFF'), [['a', '\uFEFF']]);
assert.deepEqual(parse('a;b,c', { delimiter: ';' }), [['a', 'b,c']]);
assert.deepEqual(parse('"",""'), [['', '']]);
assert.deepEqual(parse('a,b\na', { header: true }), [{ a: 'a', b: '' }]);
assert.deepEqual(parse('', { header: true }), []);
for (const d of ['"', '\r', '\n', '', ',,', 5, null]) err(() => createParser({ delimiter: d }), RangeError);
err(() => createParser().push(1), TypeError);
err(() => parse('"a" ,b'), SyntaxError, /line 1/);
err(() => parse('"a\r\nb\nc\rd"x'), SyntaxError, /line 4/);
err(() => parse('a\r\n\r\n"x'), SyntaxError, /line 3/);

// Lifecycle and incremental emission
let p = createParser();
assert.deepEqual(p.push(''), []);
assert.deepEqual(p.push('\uFEFF'), []);
assert.deepEqual(p.push('a\r'), [['a']]);
assert.deepEqual(p.push('\nb'), []);
assert.deepEqual(p.end(), [['b']]);
assert.deepEqual(p.end(), []);
err(() => p.push(''), Error);
p = createParser();
p.push('"a\r');
err(() => p.push('\n"x'), SyntaxError, /line 2/);
p = createParser();
p.push('"a');
err(() => p.end(), SyntaxError, /line 1/);

// Every 2- and 3-way split must match the single-push result.
const samples = [
  '\uFEFFa,"b""c",d\r\n"e\r\nf",g\rh\n\n"",x"y\r',
  '"q""",""""\r\n,\r\r\n"\uD83D\uDE00"\uD83D\uDE00',
];
for (const s of samples) {
  const whole = parse(s);
  for (let i = 0; i <= s.length; i++) {
    for (let j = i; j <= s.length; j++) {
      const q = createParser();
      const out = [...q.push(s.slice(0, i)), ...q.push(s.slice(i, j)), ...q.push(s.slice(j)), ...q.end()];
      assert.deepEqual(out, whole, `split ${i},${j}`);
    }
  }
  const q = createParser();
  const out = [];
  for (const c of s) out.push(...q.push(''), ...q.push(c));
  out.push(...q.end());
  assert.deepEqual(out, whole);
}
// Chunked syntax error line numbers
const bad = 'a\r\n"b\r\nc"\r\n"d"e';
for (let i = 0; i <= bad.length; i++) {
  const q = createParser();
  err(() => { q.push(bad.slice(0, i)); q.push(bad.slice(i)); }, SyntaxError, /line 4/);
}
console.log('ok', JSON.stringify(parse(samples[0])));

